def get_dates(result):
    construction_docs = []
    commissioning_docs = []

    for doc in result.get("data", []):
        date_str = doc.get("docObjRnsIssueDt")
        doc_number = doc.get("docObjRnsNum")

        if not date_str:
            continue

        dt = datetime.strptime(date_str, "%d-%m-%Y %H:%M")

        if doc.get("description") == "Разрешение на строительство":
            construction_docs.append((dt, doc_number))

        elif doc.get("description") == "Разрешение на ввод":
            commissioning_docs.append((dt, doc_number))

    construction_date = None
    rns_number = None
    if construction_docs:
        construction_date, rns_number = min(construction_docs, key=lambda x: x[0])
        construction_date = construction_date.date()

    commissioning_date = None
    rnv_number = None
    if commissioning_docs:
        commissioning_date, rnv_number = min(commissioning_docs, key=lambda x: x[0])
        commissioning_date = commissioning_date.date()

    return (
        construction_date,
        commissioning_date,
        rns_number,
        rnv_number,
    )

